export function createMultiEquityMcpResponse(symbol: string, entryId: 'equity_price_quote' | 'equity_fundamental_ratios') {
  const fixture = MULTI_EQUITY_FIXTURES[symbol];
  if (!fixture) throw new Error(`Unknown test equity symbol: ${symbol}`);
  const record = entryId === 'equity_price_quote' ? fixture.quote : fixture.ratios;
  return {
    jsonrpc: '2.0',
    id: 1,
    result: {
      structuredContent: {
        status_code: 200,
        success: true,
        data: {
          provider: 'bitget_data',
          results: [record],
        },
      },
    },
  };
}
